{/* Checkbox "Punya Opsi Kustom" ada di sini */}
<div className="flex items-center">
  <input 
    id="hasCustomOptions" 
    name="hasCustomOptions" 
    type="checkbox" 
    checked={product.hasCustomOptions || false} 
    onChange={handleChange} 
    className="..."
  />
  <label htmlFor="hasCustomOptions" className="ml-2 ...">Punya Opsi Kustom</label>
</div>

{/* ================== KONDISI DIMULAI DI SINI ================== */}
{product.hasCustomOptions && (
  <>
    {/* --- Area untuk mengaktifkan Opsi Kustom --- */}
    <div className="border-t-2 border-dashed border-gray-200 pt-6 mt-6">
      <h3 className="text-lg font-semibold text-gray-800">Aktifkan Opsi Kustom</h3>
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mt-4">
        {/* ... JSX untuk menampilkan checkbox dari MASTER_OPTIONS ... */}
      </div>
    </div>

    {/* --- Area untuk Mengedit Harga Opsi yang Aktif --- */}
    {activeCustomOptions.length > 0 && (
      <div className="border-t-2 border-dashed border-gray-200 pt-6 mt-6 space-y-4">
        <h3 className="text-lg font-semibold text-gray-800">Atur Harga Tambahan</h3>
        {/* ... JSX untuk menampilkan input harga dari activeCustomOptions ... */}
      </div>
    )}
  </>
)}
{/* ================== KONDISI BERAKHIR DI SINI ================== */}


<div className="pt-4">
  <button type="submit" /* ... */>
    Update Produk
  </button>
</div>

